    public override Dictionary<string, object> parseOrder(object order, object market = null)
    {
        //
        //      createOrder
        //      {
        //          "OrderResponse": {"pair": "BtcNis", "HasError": False, "Error": "", "Message": ""},
        //          "NewOrder": {
        //              "created": 1505531577,
        //              "type": 0,
        //              "order_type": 0,
        //              "status_type": 0,
        //              "amount": 0.01,
        //              "price": 10000,
        //              "stop": 0,
        //              "id": 9244416,
        //              "initialAmount": None,
        //          },
        //      }
        //      fetchOrder, fetchOpenOrders
        //      {
        //          "pair": "BtcNis",
        //          "status": "Completed",
        //          "created": 1535555837,
        //          "type": 0,
        //          "order_type": 0,
        //          "amount": 0.00000000,
        //          "price": 120000.00000000,
        //          "stop": 0,
        //          "id": 10555173,
        //          "initialAmount": 2.00000000
        //      }
        //
        object orderUnified = null;
        bool isNewOrder = false;
        if ((order != null && ((IDictionary<string, object>)order).ContainsKey("NewOrder")))
        {
            orderUnified = ((IDictionary<string,object>)order)["NewOrder"];
            isNewOrder = true;
        } else
        {
            orderUnified = order;
        }
        string? id = this.safeString(orderUnified, "id");
        string? symbol = this.safeSymbol(null, market);
        Int64? timestamp = this.safeIntegerProduct(orderUnified, "created", 1000);
        // status field vary between responses
        // bit2c status type:
        // 0 = New
        // 1 = Open
        // 5 = Completed
        string? status = null;
        if (isNewOrder)
        {
            Int64? tempStatus = this.safeInteger(orderUnified, "status_type");
            if ((tempStatus == 0) || (tempStatus == 1))
            {
                status = "open";
            } else if ((tempStatus == 5))
            {
                status = "closed";
            }
        } else
        {
            string? tempStatus = this.safeString(orderUnified, "status");
            if ((tempStatus == "New") || (tempStatus == "Open"))
            {
                status = "open";
            } else if ((tempStatus == "Completed"))
            {
                status = "closed";
            }
        }
        // bit2c order type:
        // 0 = LMT,  1 = MKT
        string? type = this.safeString(orderUnified, "order_type");
        if (type == "0")
        {
            type = "limit";
        } else if (type == "1")
        {
            type = "market";
        }
        // bit2c side:
        // 0 = buy, 1 = sell
        string? side = this.safeString(orderUnified, "type");
        if (side == "0")
        {
            side = "buy";
        } else if (side == "1")
        {
            side = "sell";
        }
        string? price = this.safeString(orderUnified, "price");
        string? amount = null;
        string? remaining = null;
        if (isNewOrder)
        {
            amount = this.safeString(orderUnified, "amount"); // NOTE:'initialAmount' is currently not set on new order
            remaining = this.safeString(orderUnified, "amount");
        } else
        {
            amount = this.safeString(orderUnified, "initialAmount");
            remaining = this.safeString(orderUnified, "amount");
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "id", id },
            { "clientOrderId", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "status", status },
            { "symbol", symbol },
            { "type", type },
            { "timeInForce", null },
            { "postOnly", null },
            { "side", side },
            { "price", price },
            { "triggerPrice", null },
            { "amount", amount },
            { "filled", null },
            { "remaining", remaining },
            { "cost", null },
            { "trades", null },
            { "fee", null },
            { "info", order },
            { "average", null },
        }, market);
    }

