    public virtual string? removeCommaFromValue(object str)
    {
        object newString = "";
        List<object> strParts = ((string)str).Split(new [] {","}, StringSplitOptions.None).ToList<object>();
        for (int i = 0; i < (strParts?.Count ?? 0); i++)
        {
            newString = add(newString, strParts[i]);
        }
        return ((string?)((object)(newString)));
    }

    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // public fetchTrades
        //
        //     {
        //         "date":1651785980,
        //         "price":127975.68,
        //         "amount":0.3750321,
        //         "isBid":true,
        //         "tid":1261018
        //     }
        //
        // private fetchMyTrades
        //
        //     {
        //         "ticks":1574767951,
        //         "created":"26/11/19 13:32",
        //         "action":1,
        //         "price":"1,000",
        //         "pair":"EthNis",
        //         "reference":"EthNis|10867390|10867377",
        //         "fee":"0.5",
        //         "feeAmount":"0.08",
        //         "feeCoin":"₪",
        //         "firstAmount":"-0.015",
        //         "firstAmountBalance":"9",
        //         "secondAmount":"14.93",
        //         "secondAmountBalance":"130,233.28",
        //         "firstCoin":"ETH",
        //         "secondCoin":"₪"
        //         "isMaker": True,
        //     }
        //
        Int64? timestamp = null;
        string? id = null;
        string? price = null;
        string? amount = null;
        object orderId = null;
        Dictionary<string, object> fee = null;
        object side = null;
        string? makerOrTaker = null;
        string? reference = this.safeString(trade, "reference");
        if ((reference != null))
        {
            id = reference;
            timestamp = this.safeTimestamp(trade, "ticks");
            price = this.safeString(trade, "price");
            price = this.removeCommaFromValue(price);
            amount = this.safeString(trade, "firstAmount");
            List<object> reference_parts = reference.Split(new [] {"|"}, StringSplitOptions.None).ToList<object>(); // reference contains 'pair|orderId_by_taker|orderId_by_maker'
            string? marketId = this.safeString(trade, "pair");
            market = this.safeMarket(marketId, market);
            market = this.safeMarket((reference_parts != null && 0 < reference_parts.Count ? reference_parts[0] : null), market);
            bool? isMaker = this.safeBool(trade, "isMaker");
            makerOrTaker = ((isMaker == true)) ? "maker" : "taker";
            orderId = ((isMaker == true)) ? (reference_parts != null && 2 < reference_parts.Count ? reference_parts[2] : null) : (reference_parts != null && 1 < reference_parts.Count ? reference_parts[1] : null);
            Int64? action = this.safeInteger(trade, "action");
            if ((action == 0))
            {
                side = "buy";
            } else
            {
                side = "sell";
            }
            string? feeCost = this.safeString(trade, "feeAmount");
            if ((feeCost != null))
            {
                fee = new Dictionary<string, object>() {
                    { "cost", feeCost },
                    { "currency", "NIS" },
                };
            }
        } else
        {
            timestamp = this.safeTimestamp(trade, "date");
            id = this.safeString(trade, "tid");
            price = this.safeString(trade, "price");
            amount = this.safeString(trade, "amount");
            side = this.safeValue(trade, "isBid");
            if ((side != null))
            {
                if (((side != null)) && (!isEqual(side, "")))
                {
                    side = "buy";
                } else
                {
                    side = "sell";
                }
            }
        }
        market = this.safeMarket(null, market);
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", id },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", getValue(market, "symbol") },
            { "order", orderId },
            { "type", null },
            { "side", side },
            { "takerOrMaker", makerOrTaker },
            { "price", price },
            { "amount", amount },
            { "cost", null },
            { "fee", fee },
        }, market);
    }

    public virtual bool isFiat(string? code)
    {
        return isEqual(code, "NIS");
    }

    /**
     * @method
     * @name bit2c#fetchDepositAddress
